   390→            onChange={(e) => setReviewNotes(e.target.value)}
   391→            placeholder={
   392→              reviewAction === 'approve'
   393→                ? 'Agregue notas si es necesario...'
   394→                : 'Por favor indique el motivo del rechazo...'
   395→            }
   396→          />
   397→        </DialogContent>
   398→        <DialogActions>
   399→          <Button onClick={handleCloseReview} disabled={submitting}>
   400→            Cancelar
   401→          </Button>
   402→          <Button
   403→            onClick={handleSubmitReview}
   404→            variant="contained"
   405→            color={reviewAction === 'approve' ? 'success' : 'error'}
   406→            disabled={submitting}
   407→            startIcon={submitting ? <CircularProgress size={20} /> : null}
   408→          >
   409→            {submitting
   410→              ? 'Procesando...'
   411→              : reviewAction === 'approve'
   412→              ? 'Aprobar'
   413→              : 'Rechazar'}
   414→          </Button>
   415→        </DialogActions>
   416→      </Dialog>
   417→    </Box>
   418→  );
   419→};
   420→
   421→export default FKReviewQueue;
