  match_status: 'approved' | 'pending_review' | 'rejected';
  is_manual_override: boolean;
  override_reason: string | null;
  override_type?: 'exact_match' | 'tolerance_exception' | 'customer_name_correction';
  created_at: string;
  updated_at?: string;
  created_by?: string;
}

