     2→ * Operations Service - API calls for Operations department
     3→ */
     4→import apiClient from '../api/clients/apiClient';
     5→import type {
     6→  ContractGenerationRequest,
     7→  ContractGeneration,
     8→} from '../types/legal';
     9→
    10→const BASE_URL = '/operations';
    11→
    12→export const operationsService = {
    13→  /**
    14→   * Request contract generation (Operations initiates)
    15→   */
    16→  async requestContractGeneration(
    17→    request: ContractGenerationRequest
    18→  ): Promise<ContractGeneration> {
    19→    // Create FormData for multipart/form-data (backend expects Form parameters)
    20→    const formData = new FormData();
    21→    formData.append('client_nit', request.client_nit);
    22→    formData.append('contract_type', request.contract_type || 'activos');
    23→
    24→    const response = await apiClient.post<ContractGeneration>(
    25→      `${BASE_URL}/contracts/generate`,
    26→      formData,
    27→      {
    28→        headers: {
    29→          'Content-Type': 'multipart/form-data',
    30→        },
    31→      }
    32→    );
    33→    return response.data;
    34→  },
    35→
    36→  /**
    37→   * Get all approved contracts
    38→   */
    39→  async getApprovedContracts(contractType?: string): Promise<ContractGeneration[]> {
    40→    const params = contractType ? { contract_type: contractType } : {};
    41→    const response = await apiClient.get<ContractGeneration[]>(
    42→      `${BASE_URL}/contracts/approved`,
    43→      { params }
    44→    );
    45→    return response.data;
    46→  },
    47→
    48→  /**
    49→   * Request Otrosí contract generation (Operations initiates)
    50→   */
    51→  async requestOtrosiGeneration(
    52→    clientNit: string
    53→  ): Promise<ContractGeneration> {
    54→    // Create FormData for multipart/form-data (backend expects Form parameters)
    55→    const formData = new FormData();
    56→    formData.append('client_nit', clientNit);
    57→    formData.append('contract_type', 'otrosi');
    58→
    59→    const response = await apiClient.post<ContractGeneration>(
    60→      `${BASE_URL}/contracts/generate`,
    61→      formData,
    62→      {
    63→        headers: {
    64→          'Content-Type': 'multipart/form-data',
    65→        },
    66→      }
    67→    );
    68→    return response.data;
    69→  },
    70→
    71→  /**
    72→   * Get all approved Otrosí contracts
    73→   */
    74→  async getApprovedOtrosis(): Promise<ContractGeneration[]> {
    75→    return this.getApprovedContracts('otrosi');
    76→  },
    77→
    78→  /**
    79→   * Request Inventario Bodega contract generation with RUT upload (Operations initiates)
    80→   *
    81→   * @param clientNit - Client NIT
    82→   * @param rutFile - RUT PDF document for custodian operator
    83→   */
    84→  async requestInventarioBodegaGeneration(
    85→    clientNit: string,
    86→    rutFile: File
    87→  ): Promise<ContractGeneration> {
    88→    // Create FormData for multipart/form-data upload
    89→    const formData = new FormData();
    90→    formData.append('client_nit', clientNit);
    91→    formData.append('contract_type', 'inventario_bodega');
    92→    formData.append('rut_file', rutFile);
    93→
    94→    const response = await apiClient.post<ContractGeneration>(
    95→      `${BASE_URL}/contracts/generate`,
    96→      formData,
    97→      {
    98→        headers: {
    99→          'Content-Type': 'multipart/form-data',
   100→        },
   101→      }
   102→    );
   103→    return response.data;
   104→  },
   105→
   106→  /**
   107→   * Get contract details by ID
   108→   */
   109→  async getContractDetails(contractId: string): Promise<ContractGeneration> {
   110→    const response = await apiClient.get<ContractGeneration>(
   111→      `${BASE_URL}/contracts/${contractId}`
   112→    );
   113→    return response.data;
   114→  },
   115→
   116→  /**
   117→   * Download approved contract PDF
